<script setup>
import{ref,reactive,onMounted}from'vue';import{getRequests,createQuote,getOrders,updateProgress,shipOrder,advanceLogistics,getLogistics}from'../api';import{ElMessage}from'element-plus'
const requests=ref([]),orders=ref([]),dialogs=ref({}),logistics=ref({}),form=reactive({price:0,leadDays:10,note:''})
async function load(){requests.value=(await getRequests()).data;orders.value=(await getOrders()).data;for(const o of orders.value){try{logistics.value[o.id]=(await getLogistics(o.id)).data}catch{}}}
async function quote(r){await createQuote({requestId:r.id,price:form.price,leadDays:form.leadDays,note:form.note});ElMessage.success('报价已提交');dialogs.value[r.id]=false;load()}
async function step(o,p,t){await updateProgress(o.id,{progress:p,text:t});ElMessage.success('制作进度已更新');load()}
async function ship(o){await shipOrder(o.id,{carrier:'顺丰速运（模拟）',trackingNo:''});ElMessage.success('模拟发货成功');load()}
async function advance(o){await advanceLogistics(o.id);ElMessage.success('模拟物流轨迹已更新');load()}
onMounted(load)
</script>
<template><section class="page-hero"><div class="container"><h1>创作者工作台</h1><p>需求报价、作品制作、发货和物流节点集中处理。</p></div></section><section class="section"><div class="container"><div class="admin-grid"><div><div class="section-head"><div><h2 style="font-size:24px">定制需求大厅</h2><p>选择与你擅长方向匹配的需求。</p></div></div><div class="panel" v-for="r in requests" :key="r.id" style="margin-bottom:14px"><div style="display:flex;justify-content:space-between"><b>{{r.title}}</b><span class="status">{{r.status}}</span></div><p class="body-copy">{{r.description}}</p><div class="request-meta"><span>{{r.category}} · ¥{{r.budgetMin}}-{{r.budgetMax}} · {{r.preferredMaterial}}</span><el-button size="small" @click="dialogs[r.id]=true">给出报价</el-button></div><el-dialog v-model="dialogs[r.id]" title="提交制作方案" width="430px"><el-form label-position="top"><el-form-item label="报价"><el-input-number v-model="form.price" :min="1" style="width:100%"/></el-form-item><el-form-item label="预计工期（天）"><el-input-number v-model="form.leadDays" :min="1" style="width:100%"/></el-form-item><el-form-item label="方案说明"><el-input v-model="form.note" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="dialogs[r.id]=false">取消</el-button><el-button type="primary" @click="quote(r)">提交报价</el-button></template></el-dialog></div></div>
<div><div class="section-head"><div><h2 style="font-size:24px">我的定制订单</h2><p>按订单状态执行制作和发货。</p></div></div><div class="panel creator-order" v-for="o in orders.filter(x=>!['已完成','已取消'].includes(x.status))" :key="o.id"><div class="order-title-row"><b>{{o.workTitle}}</b><span class="status">{{o.status}}</span></div><el-progress :percentage="o.progress" color="#a65f3f" style="margin:12px 0"/><p class="subtle">{{o.progressText}}</p><div class="creator-actions"><el-button v-if="o.status==='待制作'" size="small" @click="step(o,20,'已确认订单，开始准备材料')">开始制作</el-button><template v-if="o.status==='制作中'"><el-button size="small" @click="step(o,60,'主体制作完成，进入细节处理')">主体完成</el-button><el-button size="small" type="primary" @click="step(o,100,'作品制作完成并完成质检，等待发货')">制作完成</el-button></template><el-button v-if="o.status==='待发货'" size="small" type="primary" @click="ship(o)">模拟发货</el-button><el-button v-if="['已发货','运输中'].includes(o.status)" size="small" @click="advance(o)">模拟物流更新</el-button></div><div v-if="logistics[o.id]?.shipment" class="shipping-card"><b>{{logistics[o.id].shipment.carrier}}</b><span>{{logistics[o.id].shipment.trackingNo}}</span><small>{{logistics[o.id].shipment.status}}</small></div></div></div></div></div></section></template>
